  // Merge a raw career record with its category template + any per-career overrides.
  function getCareer(id) {
    const c = CAREERS_RAW[id];
    if (!c) return null;
    const cat = CATEGORIES[c.category];
    const ov = c.overrides || {};
    return {
      id: c.id, title: c.title, category: c.category, streams: c.streams,
      short: c.short, degree: c.degree, skills: c.skills, languages: c.languages,
      salary: c.salary, growth: c.growth, tags: c.tags,
      jobdesc: ov.jobdesc || cat.jobdesc.replace("{title}", c.title),
      eligibility: ov.eligibility || cat.eligibility,
      recruiters: ov.recruiters || cat.recruiters,
      colleges: ov.colleges || cat.colleges,
      exams: ov.exams || cat.exams,
      certifications: ov.certifications || cat.certifications,
      future: ov.future || cat.future.replace("{titlelow}", c.title.toLowerCase()),
      roadmap: ov.roadmap || cat.roadmap.map((s) => s.replace("{degree}", c.degree)),
    };
  }
  function allCareers() { return Object.keys(CAREERS_RAW).map(getCareer); }
  function getStream(key) { return STREAMS[key]; }
  function getRelated(career, limit) {
    limit = limit || 4;
    return Object.values(CAREERS_RAW)
      .filter((c) => c.category === career.category && c.id !== career.id)
      .slice(0, limit)
      .map((c) => c.id);
  }

